BEGIN READ ONLY;
SELECT p.oid::regprocedure AS signature,md5(replace(p.prosrc,chr(13),'')) AS body_hash,p.prosecdef,p.proconfig,has_function_privilege('anon',p.oid,'EXECUTE') AS anon_execute,has_function_privilege('authenticated',p.oid,'EXECUTE') AS authenticated_execute,has_function_privilege('service_role',p.oid,'EXECUTE') AS service_execute FROM pg_proc p WHERE p.oid IN (to_regprocedure('private.whatsapp_answer_profile(uuid,uuid)'),to_regprocedure('private.whatsapp_attempt_profile_current(uuid,uuid)'),to_regprocedure('private.wa_worker_lock(uuid,uuid,boolean)'),to_regprocedure('private.billing_service_receipt_eligible(uuid)'),to_regprocedure('private.billing_service_immutable()'),to_regprocedure('public.whatsapp_reserve_job_usage(uuid,uuid)'),to_regprocedure('public.billing_load_worker_frame(uuid,uuid)'),to_regprocedure('public.ai_reserve_whatsapp_capacity_cost_attempt(uuid,uuid,uuid,integer,text,text,numeric,text,jsonb,jsonb,text,uuid)'),to_regprocedure('public.whatsapp_retrieve_approved_knowledge(uuid,uuid,uuid,text)'),to_regprocedure('public.ai_start_whatsapp_attempt(uuid,uuid)'),to_regprocedure('public.whatsapp_stage_job_reply(uuid,uuid,uuid,jsonb)'),to_regprocedure('public.whatsapp_claim_assistant_job_send(uuid,uuid)'),to_regprocedure('public.ai_reserve_whatsapp_attempt(uuid,uuid,uuid,integer,text,text,numeric,text,jsonb,jsonb)'),to_regprocedure('public.ai_reserve_whatsapp_profile_attempt(uuid,uuid,uuid,integer,text,text,numeric,text,jsonb,jsonb,text,uuid)'));
SELECT c.oid::regclass,c.relrowsecurity FROM pg_class c WHERE c.oid IN ('private.billing_service_offers'::regclass,'private.billing_service_order_offers'::regclass,'private.billing_service_grants'::regclass);
SELECT tgrelid::regclass,tgname,tgenabled FROM pg_trigger WHERE NOT tgisinternal AND tgfoid IN ('private.billing_financial_receipt_immutability()'::regprocedure,'private.billing_service_immutable()'::regprocedure);
SELECT name,md5(replace(pg_get_viewdef(name::regclass,true),chr(13),'')) FROM (VALUES('private.billing_proven_entitlement_grants'),('private.billing_verified_collection_history')) v(name);
SELECT role_name,table_name,has_table_privilege(role_name,table_name,'SELECT,INSERT,UPDATE,DELETE') AS table_dml FROM (VALUES('anon'),('authenticated'),('service_role')) roles(role_name) CROSS JOIN (VALUES('private.billing_service_offers'),('private.billing_service_order_offers'),('private.billing_service_grants')) tables(table_name);
COMMIT;
